/// <summary>
/// PaffH 16.04.21
/// </summary>
/// <param name = "_ProdBOM">ProdBOM</param>
/// <returns>ImageRes</returns>
[SuppressBPWarning('BPParameterNotUsed','_ProdBOM')]
public static display ImageRes SIM_KCS_InventOnhandImage(ProdBOM _ProdBOM)
{
    return ProdBOM::SIM_KCS_InventOnhandId();
}

/// <summary>
/// PaffH 16.04.21
/// </summary>
/// <param name = "_ProdBOM">ProdBOM</param>
/// <returns>ImageRes</returns>
public static display ImageRes ItemTypeImage(ProdBOM _ProdBOM)
{
    return _ProdBOM.inventTable().inventItemType().imageRessNo();
}

/// <summary>
/// PaffH 16.04.21
/// </summary>
/// <returns>ImageRes</returns>
public static ImageRes SIM_KCS_InventOnhandId()
{
    #resAppl

    RandomGenerate randomGenerate = RandomGenerate::construct();
    int randoValue = randomGenerate.randomInt(1,3);

    switch (randoValue)
    {
        case 1: 
            return #Image_OK;
        case 2: 
            return #ImageError;
        default: 
            return #ImageProcess;
    }

}
